WITH reason_refunds AS ( SELECT cr.cr_reason_sk, SUM(cr.cr_refunded_cash) AS total_refunded_cash, SUM(cr.cr_store_credit) AS total_store_credit, COUNT(*) AS total_returns FROM catalog_returns cr GROUP BY cr.cr_reason_sk ), latest_return AS ( SELECT cr.cr_reason_sk, MAX(d.d_date) AS last_return_date FROM catalog_returns cr JOIN date_dim d ON cr.cr_returned_date_sk = d.d_date_sk GROUP BY cr.cr_reason_sk ), ratio_calc AS ( SELECT r.cr_reason_sk, r.total_refunded_cash, r.total_store_credit, r.total_returns, CASE WHEN (r.total_refunded_cash + r.total_store_credit) = 0 THEN 0 ELSE r.total_refunded_cash / (r.total_refunded_cash + r.total_store_credit) END AS cash_refund_ratio, l.last_return_date FROM reason_refunds r JOIN latest_return l ON r.cr_reason_sk = l.cr_reason_sk ) SELECT rc.cr_reason_sk, rc.total_returns, rc.total_refunded_cash, rc.total_store_credit, rc.cash_refund_ratio, PERCENT_RANK() OVER (ORDER BY rc.cash_refund_ratio) AS cash_refund_percentile, NTILE(4) OVER (ORDER BY rc.cash_refund_ratio) AS quartile_bucket, CASE WHEN rc.cash_refund_ratio >= 0.75 THEN 'High Cash Refund' WHEN rc.cash_refund_ratio >= 0.5 THEN 'Medium Cash Refund' ELSE 'Low Cash Refund' END AS cash_refund_category, DATE_DIFF('day', rc.last_return_date, CURRENT_DATE) AS days_since_last_return FROM ratio_calc rc ORDER BY rc.cash_refund_ratio DESC
